      tasks = tasks.map((item) => item.id === saved.id ? saved : item);
      renderTasks();
    } catch (failure) {
      checkbox.checked = task.completed;
      showError(failure.message);
    } finally {
      checkbox.disabled = archived;
    }
  });
  row.append(checkbox, title);
  return row;
}

